import re

from .parser import rows

_QTY = re.compile(r'[0-9]+')


def _parse_qty(value):
    if _QTY.fullmatch(value) is None:
        return None
    return int(value)


def import_text(text, store):
    report = {'seen': 0, 'imported': 0, 'rejected': 0, 'quantity': 0}
    for parts in rows(text):
        report['seen'] += 1
        if parts is None or len(parts) != 3:
            report['rejected'] += 1
            continue
        sku, name, qty_text = (part.strip() for part in parts)
        qty = _parse_qty(qty_text)
        if not sku or not name or qty is None:
            report['rejected'] += 1
            continue
        store.put(sku, name, qty)
        report['imported'] += 1
        report['quantity'] += qty
    return report

